/* the #wizdispmacros command
 * Verify that some display macros are returning sane values */
const __static_wiz_display_macros_display_issues = cptr.bytes("Display macro issues:"); /** C ref: wizcmds.c:1707 — char[22] (function-static) */

/** C ref: wizcmds.c:1705 @returns {CInt} */
export function wiz_display_macros() {
    let buf = new Uint8Array(256);
    let win;
    let glyph;
    let test;
    let trouble = 0;
    let no_glyph = NHC.MAX_GLYPH;
    let max_glyph = NHC.MAX_GLYPH;

    win = create_nhwindow()(NHM.NHW_TEXT);

    for (glyph = 0; glyph < NHC.MAX_GLYPH; ++glyph) {
        /* glyph_is_cmap / glyph_to_cmap() */
        if (glyph_is_cmap(glyph)) {
            test = glyph_to_cmap(glyph);
            /* check for MAX_GLYPH return */
            if (test == no_glyph) {
                if (!trouble++)
                    putstr()(win, 0, cptr.decay(__static_wiz_display_macros_display_issues));
                void cptr.sprintf(
                    cptr.decay(buf),
                    __s_glyph_is_cmap_glyph_to_cmap_glyph_d,
                    glyph,
                    test
                );
                putstr()(win, 0, cptr.decay(buf));
            }
            if (glyph_is_cmap_zap(glyph) && !(test >= NHC.S_vbeam && test <= NHC.S_rslant)) {
                if (!trouble++)
                    putstr()(win, 0, cptr.decay(__static_wiz_display_macros_display_issues));
                void cptr.sprintf(
                    cptr.decay(buf),
                    __s_glyph_is_cmap_zap_glyph_d_returned_non,
                    glyph,
                    test
                );
                putstr()(win, 0, cptr.decay(buf));
            }
            /* check against defsyms array subscripts */
            if (!((test) >= 0 && (test) < 106)) {
                if (!trouble++)
                    putstr()(win, 0, cptr.decay(__static_wiz_display_macros_display_issues));
                void cptr.sprintf(
                    cptr.decay(buf),
                    __s_glyph_to_cmap_glyph_d_returns_d_exceeds,
                    glyph,
                    test,
                    106,
                    max_glyph
                );
                putstr()(win, 0, cptr.decay(buf));
            }
        }
        /* glyph_is_monster / glyph_to_mon */
        if (glyph_is_monster(glyph)) {
            test = glyph_to_mon(glyph);
            /* check against mons array subscripts */
            if (test < 0 || test >= NHC.NUMMONS) {
                if (!trouble++)
                    putstr()(win, 0, cptr.decay(__static_wiz_display_macros_display_issues));
                void cptr.sprintf(
                    cptr.decay(buf),
                    __s_glyph_to_mon_glyph_d_returns_d_exceeds,
                    glyph,
                    test,
                    NHC.NUMMONS
                );
                putstr()(win, 0, cptr.decay(buf));
            }
        }
        /* glyph_is_object / glyph_to_obj */
        if (glyph_is_object(glyph)) {
            test = glyph_to_obj(glyph);
            /* check against objects array subscripts */
            if (test < 0 || test > NHC.NUM_OBJECTS) {
                if (!trouble++)
                    putstr()(win, 0, cptr.decay(__static_wiz_display_macros_display_issues));
                void cptr.sprintf(
                    cptr.decay(buf),
                    __s_glyph_to_obj_glyph_d_returns_d_exceeds,
                    glyph,
                    test,
                    NHC.NUM_OBJECTS
                );
                putstr()(win, 0, cptr.decay(buf));
            }
        }
    }
    if (!trouble)
        putstr()(win, 0, __s_no_display_macro_issues_detected);
    display_nhwindow()(win, 0);
    destroy_nhwindow()(win);
    return NHM.ECMD_OK;
}

