    let otyp;
    let oclass = cptr.ld1so2(objects, NHC.FIRST_OBJECT, $sizeof_objclass, $objclass_oc_class);
    __builtin___memset_chk(probsum, 0, 72n, __builtin_object_size(probsum, 0));

